<script setup lang="ts">import {ref,onMounted} from 'vue';import {reviews} from '../stores/reviews';import {reports} from '../stores/reports';import {isAdmin} from '../stores/auth';import {request,downloadCsv} from '../api/client';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import StatusPill from '../components/common/StatusPill.vue';import ProbabilitySummary from '../components/ProbabilitySummary.vue';const expanded=ref('');const {error,busy,act}=useTask();onMounted(()=>Promise.all([reviews.load(),reports.load()]));function approve(id:string){act(async()=>{await request('/reviews/'+id+'/approve','POST');await reviews.load()})}function publish(id:string){act(async()=>{await reports.create({review_id:id,title:'证据推理底稿 '+new Date().toLocaleDateString()})})}function download(id:string){act(()=>downloadCsv(id))}</script><template><PageHeading index="05 / 研修归档" title="把版本、分支与研修边界，一并签入底稿。" note="主管批准后生成不可变报告。CSV区分后验、候选和分支，保留基准logZ/下溢、分支联合logZ、熵、原始IG和版本。"/><Notice :message="error"/><div class="two-col"><section><h2>证据复核</h2><article v-for="r in reviews.items.value" :key="r.id" class="review-row"><StatusPill :status="r.state"/><p>{{r.action}}</p><small>{{r.reviewer||'等待主管批准'}}</small><div class="actions" v-if="isAdmin()"><button v-if="r.state==='submitted'" @click="approve(r.id)" :disabled="busy">批准证据复核</button><button v-if="r.state==='approved'" class="secondary" @click="publish(r.id)" :disabled="busy">生成推理快照</button></div></article></section><section><h2>批准研修底稿</h2><article v-for="r in reports.items.value" :key="r.id" class="report-row"><p class="eyebrow">APPROVED EVIDENCE RECORD</p><h3>{{r.title}}</h3><p>{{r.snapshot.result.case_name}}</p><p>CPT {{r.snapshot.result.version}} · {{r.snapshot.reviewer}}</p><div class="actions"><button @click="download(r.id)">下载推理 CSV ↓</button><button class="secondary" @click="expanded=expanded===r.id?'':r.id">查看证据分母</button></div><ProbabilitySummary v-if="expanded===r.id" :result="r.snapshot.result"/></article></section></div></template>
